          Confirmar reserva &lt;i class=&quot;bi bi-arrow-right ms-2&quot;&gt;&lt;/i&gt;
        &lt;/button&gt;
        &lt;p class=&quot;text-center text-muted small w-100 mb-0 mt-2&quot; id=&quot;mensajeSeleccion&quot;&gt;
